// Reconstruit des fiches minimales pour /api/digest.
// La logique d'URGENCE vit dans l'app (lib/priorites.ts) — ici on ne fait
// que traduire les colonnes du Sheet en champs qu'elle sait lire :
//   société, étape, prochaine étape datée (deadline), dernier contact.
// construireJournee déclenche le cadran « faire » sur : deadline en retard
// ou du jour, RDV du jour/lendemain, et deals avancés qui refroidissent.

const STAGE_ALIAS = { prospect:'prospect', contact:'contact', audit:'audit', demo:'demo', 'démo':'demo', offre:'offre', 'red zone':'redzone', redzone:'redzone', 'red-zone':'redzone', signe:'signe', 'signé':'signe', gagne:'signe', perdu:'perdu' };
const norm = (s) => String(s || '').trim().toLowerCase();
const toISO = (v) => {
  if (!v) return null;
  // Accepte 2026-08-07, 07/08/2026, 7 août… (best effort)
  const iso = String(v).match(/(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return new Date(iso[0] + 'T09:00:00').toISOString();
  const fr = String(v).match(/(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})/);
  if (fr) { const [_, d, m, y] = fr; const yy = y.length === 2 ? '20'+y : y; return new Date(`${yy}-${m.padStart(2,'0')}-${d.padStart(2,'0')}T09:00:00`).toISOString(); }
  return null;
};

const prospects = [];
let i = 0;
for (const it of items) {
  const r = it.json || {};
  const company = r.prospect || r.company || r.entreprise || r.société || r.societe;
  if (!company) continue;
  const stage = STAGE_ALIAS[norm(r.stage || r['étape'] || r.etape)] || 'prospect';
  const deadline = toISO(r.deadline || r['échéance'] || r.echeance);
  const lastTouch = toISO(r.lastContact || r['dernier contact'] || r.history_date || r.updatedAt);
  prospects.push({
    id: 'sheet-' + (i++),
    company: String(company),
    name: r.contact || r.name || '',
    sector: 'autre',
    city: r.city || r.ville || '',
    stage,
    probability: 50,
    trust: 20,
    monthlyValue: Number(r.monthlyValue || r.mrr || 0) || 0,
    setupValue: Number(r.setupValue || 990) || 990,
    ignoranceTax: 0,
    nextStep: deadline ? { date: deadline, action: (r.deadline_action || 'Prochaine étape') } : null,
    events: lastTouch ? [{ id: 'e'+i, date: lastTouch, kind: 'note', summary: 'dernier contact' }] : [],
    objections: [], obstacles: [], problems: [], attachments: [], payments: [],
    deepAudit: {}, tags: [], notes: '',
    createdAt: lastTouch || new Date().toISOString(), updatedAt: lastTouch || new Date().toISOString(),
  });
}
return [{ json: { prospects, meetings: [] } }];
